\section{Introduction}

The symmetric group $S_n$ is the group of all bijections of an $n$-element set under composition; it has order $n!$. Two of its most basic invariants are intertwined cleanly:
\begin{enumerate}
  \item the \emph{conjugacy classes} of $S_n$, the orbits under $\tau \mapsto \rho\,\tau\,\rho^{-1}$; and
  \item the \emph{partitions} of $n$, the multisets of positive integers summing to $n$.
\end{enumerate}
The classical theorem connecting them states that two permutations are conjugate in $S_n$ if and only if they have the same multiset of cycle lengths, and that every such multiset summing to $n$ is realized. Consequently conjugacy classes of $S_n$ are indexed by partitions of $n$. This fact is the gateway to the representation theory of $S_n$: by Frobenius, the irreducible complex representations of $S_n$ are themselves indexed by partitions of $n$ (Specht modules), so the character table of $S_n$ is a square matrix of side $p(n)$ whose rows and columns are both naturally labeled by $\Par(n)$.

This paper records a from-scratch, machine-verified construction of the indexing bijection itself --- not merely a cardinality equality, but an explicit equivalence of sets with an inverse, together with the supporting lemmas.

\subsection{Notation and conventions}
\begin{itemize}
  \item $\Par(n)$ denotes the set of partitions of $n$, i.e.\ finite multisets of positive integers with sum $n$.
  \item For a permutation $\sigma$, the \emph{cycle type} $\cycleType(\sigma)$ is the multiset of lengths of the disjoint cycles of $\sigma$ that have length $\ge 2$. Fixed points (length-$1$ cycles) are \emph{not} recorded.
  \item The \emph{partition of a permutation} $\partn(\sigma)$ is the full partition of $n$ obtained from $\cycleType(\sigma)$ by appending $n - |\cycleType(\sigma)|$ parts equal to $1$, where $|\cdot|$ denotes the multiset sum. Thus $\partn(\sigma)$ records all cycle lengths, including fixed points, and its parts sum to $n$.
  \item $\Conj(S_n)$ denotes the set of conjugacy classes of $S_n$, and $\IsConj(\sigma,\tau)$ means $\sigma,\tau$ are conjugate.
\end{itemize}
We realize $S_n$ concretely as $\Perm(\Fin\, n)$, the permutations of the standard $n$-element type.

\section{Background lemmas (imported, stated for completeness)}

\begin{fact}[Existence of permutations with prescribed cycle type]\label{fact:exist}
A multiset $m$ of positive integers is the cycle type of some permutation of an $n$-element set if and only if every element of $m$ is $\ge 2$ and the sum of $m$ is at most $n$.
\end{fact}

\begin{fact}[Conjugacy detects the partition]\label{fact:conj}
For $\sigma,\tau \in S_n$, $\ \IsConj(\sigma,\tau) \iff \partn(\sigma) = \partn(\tau)$.
\end{fact}

Both facts are classical and available in the formalization's ambient library; the contribution here is to leverage them into an explicit, invertible indexing of conjugacy classes by partitions.

\section{The forward construction: from partitions to permutations}

\subsection{Realizing the larger parts as a cycle type}

\begin{lemma}[\texttt{exists\_perm\_cycleType}]\label{lem:exist}
For every partition $p \in \Par(n)$ there exists $g \in S_n$ with
\[
  \cycleType(g) = \{\, a \in p : a \ge 2 \,\}
\]
(the sub-multiset of parts of $p$ that are at least $2$).
\end{lemma}

\begin{proof}[Proof sketch]
Let $m = \{a \in p : a \ge 2\}$. Every element of $m$ is $\ge 2$ by construction, and $|m| \le |p| = n$ because $m$ is a sub-multiset of $p$ and $p$ sums to $n$. By Fact~\ref{fact:exist}, $m$ is the cycle type of some permutation.
\end{proof}

\begin{definition}[\texttt{permOfPartition}]\label{def:pi}
For $p \in \Par(n)$, let $\pi_p$ be a permutation provided by Lemma~\ref{lem:exist}, so that
\[
  \cycleType(\pi_p) = \{\, a \in p : a \ge 2 \,\}. \tag{\texttt{permOfPartition\_cycleType}}
\]
Geometrically, $\pi_p$ arranges $\{1,\dots,n\}$ into disjoint blocks whose sizes are the parts of $p$ and turns each block of size $\ge 2$ into a single cycle, leaving the size-$1$ blocks as fixed points.
\end{definition}

\subsection{Restoring the fixed points: the key lemma}

\begin{lemma}[\texttt{permOfPartition\_partition\_parts}]\label{lem:key}
For every $p \in \Par(n)$, $\ \partn(\pi_p) = p$ (equality of partitions, i.e.\ equality of their parts as multisets).
\end{lemma}

\begin{proof}[Proof sketch]
By definition of $\partn$ and Definition~\ref{def:pi},
\[
  \partn(\pi_p) = \cycleType(\pi_p) \uplus \replicate\!\big(n - |\cycleType(\pi_p)|,\ 1\big)
  = \{a \in p : a \ge 2\} \uplus \replicate(k,1),
\]
where $k = n - \sum_{a \in p,\, a \ge 2} a$. Compare with the decomposition of $p$ into large and small parts,
\[
  p = \{a \in p : a \ge 2\} \uplus \{a \in p : a < 2\}.
\]
Since every part of a partition is positive, each element of $\{a \in p : a < 2\}$ equals $1$; hence $\{a \in p : a < 2\} = \replicate(\ell,1)$ for some $\ell$. Summing $p$ gives $\sum_{a \ge 2} a + \ell = n$, so $\ell = n - \sum_{a \ge 2} a = k$. Thus the small-part blocks coincide, and adding the shared large-part block yields $\partn(\pi_p) = p$.
\end{proof}

This lemma is the technical crux: it certifies that $p \mapsto \pi_p$ loses no information through the fixed-point suppression built into the cycle-type convention.

\section{The backward construction: from permutations to partitions}

\begin{definition}[\texttt{permPartition}]\label{def:pp}
For $\sigma \in S_n$, define $\operatorname{permPartition}(\sigma) \in \Par(n)$ to be $\partn(\sigma)$, viewed as a partition of the number $n$. A re-indexing is required because $\partn(\sigma)$ is a priori a partition of $\card(\Fin\, n)$; the canonical identification $\card(\Fin\, n) = n$ supplies it.
\end{definition}

\begin{lemma}[\texttt{parts\_cast}]\label{lem:cast}
Transporting a partition along an equality of its underlying integer leaves its multiset of parts unchanged.
\end{lemma}

\begin{lemma}[\texttt{permPartition\_parts}]\label{lem:ppparts}
For every $\sigma$, $\operatorname{permPartition}(\sigma)$ has the same parts as $\partn(\sigma)$. \textup{(Immediate from Lemma~\ref{lem:cast}.)}
\end{lemma}

\begin{lemma}[\texttt{isConj\_permOfPartition}]\label{lem:isconj}
If $\sigma \in S_n$ satisfies $\partn(\sigma) = p$ (as multisets of parts), then $\IsConj(\pi_p, \sigma)$.
\end{lemma}

\begin{proof}[Proof sketch]
By Fact~\ref{fact:conj} it suffices to show $\partn(\pi_p) = \partn(\sigma)$. By Lemma~\ref{lem:key}, $\partn(\pi_p) = p = \partn(\sigma)$.
\end{proof}

\section{The bijection}

\begin{definition}[\texttt{toConjClass}]\label{def:phi}
$\Phi : \Par(n) \to \Conj(S_n)$, $\ \Phi(p) := [\pi_p]$, the conjugacy class of $\pi_p$.
\end{definition}

\begin{definition}[\texttt{ofConjClass}]\label{def:psi}
$\Psi : \Conj(S_n) \to \Par(n)$, $\ \Psi(c) := \operatorname{permPartition}(\sigma)$ for any representative $\sigma \in c$. This is well defined: if $\sigma,\sigma'$ are conjugate then by Fact~\ref{fact:conj} they have equal partitions, so $\operatorname{permPartition}(\sigma) = \operatorname{permPartition}(\sigma')$. \textup{(Lemma \texttt{ofConjClass\_mk} records $\Psi([\sigma]) = \operatorname{permPartition}(\sigma)$.)}
\end{definition}

\begin{lemma}[\texttt{toConjClass\_injective}]\label{lem:inj}
$\Phi$ is injective.
\end{lemma}

\begin{proof}[Proof sketch]
Suppose $\Phi(p) = \Phi(q)$, i.e.\ $[\pi_p] = [\pi_q]$, so $\IsConj(\pi_p,\pi_q)$. By Fact~\ref{fact:conj}, $\partn(\pi_p) = \partn(\pi_q)$. By Lemma~\ref{lem:key} these equal $p$ and $q$, hence $p = q$.
\end{proof}

\begin{lemma}[\texttt{toConjClass\_surjective}]\label{lem:surj}
$\Phi$ is surjective.
\end{lemma}

\begin{proof}[Proof sketch]
Let $c \in \Conj(S_n)$ and choose a representative $\sigma \in c$. Put $p := \operatorname{permPartition}(\sigma)$. By Lemma~\ref{lem:isconj} (with $\partn(\sigma) = p$ via Lemma~\ref{lem:ppparts}), $\IsConj(\pi_p, \sigma)$, so $[\pi_p] = [\sigma] = c$. Thus $\Phi(p) = c$.
\end{proof}

\begin{theorem}[Main, \texttt{partitionEquivConjClasses}]\label{thm:main}
For every $n \in \mathbb{N}$, the maps $\Phi$ and $\Psi$ are mutually inverse, giving an explicit equivalence
\[
  \Par(n) \;\simeq\; \Conj(S_n).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$\Phi$ is a bijection by Lemmas~\ref{lem:inj} and \ref{lem:surj}. We verify the inverse is $\Psi$ directly.
\begin{itemize}
  \item $\Psi(\Phi(p)) = \Psi([\pi_p]) = \operatorname{permPartition}(\pi_p)$, whose parts equal $\partn(\pi_p) = p$ by Lemmas~\ref{lem:ppparts} and \ref{lem:key}; hence $\Psi(\Phi(p)) = p$.
  \item For $\Phi(\Psi(c))$, pick $\sigma \in c$; then $\Psi(c) = \operatorname{permPartition}(\sigma) =: p$ and, as in Lemma~\ref{lem:surj}, $\Phi(p) = [\pi_p] = [\sigma] = c$.
\end{itemize}
Thus $\Psi = \Phi^{-1}$.
\end{proof}

\begin{corollary}[Counting]\label{cor:count}
The number of conjugacy classes of $S_n$ equals the partition number $p(n)$:
\[
  |\Conj(S_n)| = p(n).
\]
In particular $|\Conj(S_3)| = 3$, $|\Conj(S_4)| = 5$, $|\Conj(S_5)| = 7$.
\end{corollary}

\begin{proof}
A bijection of finite sets preserves cardinality; apply Theorem~\ref{thm:main} and recall $|\Par(n)| = p(n)$.
\end{proof}

\section{Consequence for character tables}

For any finite group $G$, the number of irreducible complex characters equals the number of conjugacy classes; hence the character table is square. Specializing to $G = S_n$ and invoking Corollary~\ref{cor:count}:

\begin{proposition}\label{prop:square}
The character table of $S_n$ is a square matrix of side $p(n)$. For $n = 3, 4, 5$ the tables are $3\times3$, $5\times5$, and $7\times7$ respectively.
\end{proposition}

This is precisely the ``column count'' needed before any explicit character table of $S_n$ can be assembled: it tells us how many irreducible representations to find (the rows) and how many conjugacy classes to evaluate them on (the columns), and that the two counts agree.

\section{Algorithmic content}

The proof is constructive and yields directly executable procedures:
\begin{enumerate}
  \item \textbf{Enumerate $\Par(n)$} by recursion on largest-part-bounded partitions; the count is $p(n)$.
  \item \textbf{Realize a partition as a permutation} via $\pi_p$: lay $\{1,\dots,n\}$ into consecutive blocks of the prescribed sizes and cycle each block.
  \item \textbf{Classify a permutation} via $\operatorname{permPartition}$: compute the disjoint-cycle decomposition and read off the sorted multiset of cycle lengths (including fixed points).
  \item \textbf{Conjugacy test}: two permutations are conjugate iff step (3) produces equal partitions (Fact~\ref{fact:conj}).
\end{enumerate}
These primitives compute the full conjugacy-class census of $S_n$ --- with class sizes via the centralizer-order formula $|Z(\sigma)| = \prod_i i^{m_i} m_i!$ (where $m_i$ is the number of parts equal to $i$) and class size $n!/|Z(\sigma)|$ --- and verify $\sum_{\text{classes}} (\text{class size}) = n!$ as a consistency check.

\section{Discussion}

The result sits at the confluence of combinatorics (the partition function $p(n)$, with $p(n) \sim \tfrac{1}{4n\sqrt3} e^{\pi\sqrt{2n/3}}$, now counts conjugacy classes of $S_n$), group theory (conjugacy in $S_n$ is governed entirely by cycle structure), and representation theory (the squareness of the character table and the partition-indexing of both axes launch the Murnaghan--Nakayama rule and the hook-length formula). The formalization's care around the cycle-type convention --- fixed points suppressed and explicitly restored (Lemma~\ref{lem:key}) --- is exactly the kind of detail informal treatments gloss over.

\section{Future directions}

\textbf{C1. Conjugacy-class size formula.} For $\sigma \in S_n$ with $m_i$ parts equal to $i$, $|Z(\sigma)| = \prod_i i^{m_i} m_i!$ and class size $n!/\prod_i i^{m_i} m_i!$; testable form: the sum over classes equals $n!$.

\textbf{C2. Classes splitting in $A_n$.} A class of $S_n$ inside $A_n$ splits into two $A_n$-classes iff its cycle type has distinct odd parts; conjecture: $|\Conj(A_n)| = \#\{p \text{ even}\} + \#\{p \text{ distinct odd parts}\}$.

\textbf{C3. Counting by number of cycles.} The number of $\sigma \in S_n$ with exactly $k$ cycles is $c(n,k)$ (unsigned Stirling, first kind); $\sum_k c(n,k)x^k = x(x+1)\cdots(x+n-1)$, $\sum_k c(n,k) = n!$.

\textbf{C4. Self-conjugate partitions.} The number of self-conjugate partitions of $n$ equals the number of partitions into distinct odd parts.

\textbf{C5. Column sums.} For any finite group, the sum of a fixed column (indexed by $g$) equals $\#\{x : x^2 = g\}$; for $S_n$, $\sum_\chi \chi(\sigma) = \#\{\tau : \tau^2 = \sigma\}$.

\section{Conclusion}

We have given a complete, constructive, machine-checked bijection between partitions of $n$ and conjugacy classes of $S_n$, with an explicit inverse and full supporting lemmas. The central difficulty --- reconstructing a permutation's partition from its fixed-point-suppressed cycle type --- is resolved by Lemma~\ref{lem:key}. The immediate corollary fixes the side length of the symmetric group's character table at $p(n)$, the indispensable first ingredient for any explicit character-table computation for $S_3$, $S_4$, $S_5$, and beyond.

